$count=0;$diff=array();function s_norm($v){if(is_object($v)){$o=new stdClass();$p=get_object_vars($v);ksort($p);foreach($p as $k=>$x){$o->$k=s_norm($x);}return $o;}if(is_array($v)){return array_map('s_norm',$v);}if(is_string($v)&&preg_match('/^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:/',$v)){return (new DateTimeImmutable($v,new DateTimeZone('UTC')))->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s.u');}return $v;}
function s_check($label,$a,$e){global $count,$diff;$a=s_norm(json_decode(json_encode($a,JSON_THROW_ON_ERROR)));$e=s_norm(json_decode(json_encode($e,JSON_THROW_ON_ERROR)));if(json_encode($a)===json_encode($e)){$count++;}elseif(count($diff)<8){$diff[]=array('case'=>$label,'actual'=>$a,'expected'=>$e);}}
